  F1D6: fb                       mov R3,A                    ; data: the port
  F1D7: 7c 00                    mov R4,#0x00
  F1D9: 7d 37                    mov R5,#0x37
  F1DB: 7f 80                    mov R7,#0x80
  F1DD: 12 4f ad                 lcall 0x4FAD                ; i2c_write_reg: target = port
  F1E0: 75 f0 40                 mov 0xF0,#64              ; B: polls left
pr_fs_poll:
  F1E3: 7f 80                    mov R7,#0x80
  F1E5: 7c 00                    mov R4,#0x00
  F1E7: 7d 38                    mov R5,#0x38              ; calculator result
  F1E9: 12 4c df                 lcall 0x4CDF                ; i2c_read_reg16 -> R7
  F1EC: ef                       mov A,R7
  F1ED: 20 e7 08                 jb ACC.7,pr_fs_again        ; still calculating
  F1F0: c4                       swap A
  F1F1: 54 07                    anl A,#0x07
  F1F3: b5 00 02                 cjne A,0x00,pr_fs_again     ; a result for another port (R0 is direct 0x00)
  F1F6: 80 03                    sjmp pr_fs_done
pr_fs_again:
  F1F8: d5 f0 e8                 djnz 0xF0,pr_fs_poll
pr_fs_done:
  F1FB: ef                       mov A,R7
  F1FC: 12 f2 3e                 lcall pr_sp_hex
  F1FF: 08                       inc R0
  F200: b8 08 d2                 cjne R0,#8,pr_fs_port
  F203: d0 e0                    pop ACC
  F205: fb                       mov R3,A                    ; stock's target back
  F206: 7c 00                    mov R4,#0x00
  F208: 7d 37                    mov R5,#0x37
  F20A: 7f 80                    mov R7,#0x80
  F20C: 02 4f ad                 ljmp 0x4FAD                 ; i2c_write_reg, then return
