  F212: 70 18                    jnz pr_regs_rd
  F214: 90 f2 a2                 mov DPTR,#pr_s_crlf
  F217: 12 f2 5f                 lcall pr_str
  F21A: e8                       mov A,R0
  F21B: 12 f2 47                 lcall pr_hex
  F21E: 74 20                    mov A,#0x20
  F220: 12 f2 57                 lcall pr_tx
  F223: e9                       mov A,R1
  F224: 12 f2 47                 lcall pr_hex
  F227: 74 3a                    mov A,#0x3A                 ; ':'
  F229: 12 f2 57                 lcall pr_tx
pr_regs_rd:
  F22C: e9                       mov A,R1
  F22D: fd                       mov R5,A                    ; register (R4:R5, only R5 is sent)
  F22E: 7c 00                    mov R4,#0x00
  F230: e8                       mov A,R0
  F231: ff                       mov R7,A                    ; device
  F232: 12 4c df                 lcall 0x4CDF                ; i2c_read_reg16 -> R7 (0 after 5 NACKs)
  F235: ef                       mov A,R7
  F236: 12 f2 3e                 lcall pr_sp_hex
  F239: 09                       inc R1
  F23A: d5 f0 d2                 djnz 0xF0,pr_regs         ; B
  F23D: 22                       ret
            ; pr_sp_hex: " " then A in hex. pr_hex: A in hex. pr_nib: low nibble of A as one digit.
            ; pr_tx: A on UART1, waits for TI (ES is off). pr_str: the string at DPTR until 0.
