            ; ds_select: replaces ir_cmd_to_key's entry (0x5D10). Raw NEC command 0x6A -> internal key in R7.
            ; RAM: g_ir_cmd 0x6A, g_input 0x47, g_power_on 0x4F, g_ui_page 0x45, g_osd_timer 0x27:0x28, g_ir_key2 0x6F
ds_select:
  F2B8: e5 6a                    mov A,0x6A                  ; raw NEC command byte
  F2BA: c3                       clr C
  F2BB: 94 10                    subb A,#0x10              ; A = cmd - 0x10 ; C=1 if cmd < 0x10
  F2BD: 40 46                    jc ds_stock                 ; below range -> stock path
  F2BF: b4 06 00                 cjne A,#6,ds_c1            ; never branches; sets C=1 if A < 6
ds_c1:
  F2C2: 50 23                    jnc ds_power                ; A >= 6 (cmd > 0x15) -> the power commands, or the stock path
  F2C4: ff                       mov R7,A                    ; R7 = index 0..5
  F2C5: e5 4f                    mov A,0x4F                  ; g_power_on
  F2C7: 60 18                    jz ds_eat                   ; standby -> ignore
  F2C9: e5 45                    mov A,0x45                  ; g_ui_page
  F2CB: 64 01                    xrl A,#1                    ; zero iff page == 1 (home)
  F2CD: 70 12                    jnz ds_eat                  ; in a menu -> ignore
  F2CF: ef                       mov A,R7
  F2D0: 04                       inc A                       ; input number 1..6
  F2D1: b5 47 02                 cjne A,0x47,ds_apply        ; not the current input -> switch
  F2D4: 80 0b                    sjmp ds_eat                 ; already selected -> ignore (no re-init, no OSD)
ds_apply:
  F2D6: f5 47                    mov 0x47,A                  ; g_input = target
  F2D8: 75 27 00                 mov 0x27,#0x00              ; g_osd_timer: show the input name, as a real press does
  F2DB: 75 28 c8                 mov 0x28,#0xC8
  F2DE: 12 56 40                 lcall 0x5640                ; input_apply: switch hardware + refresh display
ds_eat:
  F2E1: 7f ff                    mov R7,#0xFF                ; return "no key" to read_key
ds_key:
  F2E3: e4                       clr A
  F2E4: f5 6f                    mov 0x6F,A                  ; g_ir_key2: stock side effect of ir_cmd_to_key
  F2E6: 22                       ret
ds_power:
  F2E7: b4 06 06                 cjne A,#6,ds_off           ; A = cmd - 0x10: 6 is power on, else see if it is power off
  F2EA: e5 4f                    mov A,0x4F                  ; power on: g_power_on
  F2EC: 70 f3                    jnz ds_eat                  ; already on -> ignore, whatever the page
  F2EE: 80 11                    sjmp ds_pwr                 ; standby -> the Power key: standby_key powers on
ds_off:
  F2F0: b4 07 12                 cjne A,#7,ds_stock         ; 7 is power off; above -> stock path ("no key" past the table)
  F2F3: e5 4f                    mov A,0x4F                  ; power off: g_power_on
  F2F5: 60 ea                    jz ds_eat                   ; already in standby -> ignore (never key 0x10: the bootloader jump)
  F2F7: e5 45                    mov A,0x45                  ; g_ui_page
  F2F9: c3                       clr C
  F2FA: 94 03                    subb A,#3
  F2FC: 40 03                    jc ds_pwr                   ; home or volume page: the dispatcher runs key_power_off on Power
  F2FE: 12 0c e9                 lcall 0x0CE9                ; a menu page: key_exit_to_home first, as the dispatcher's Power does there
ds_pwr:
  F301: 7f 1f                    mov R7,#0x1F              ; the stock Power key
  F303: 80 de                    sjmp ds_key
ds_stock:
  F305: e5 6a                    mov A,0x6A                  ; replay the displaced stock instructions
  F307: b4 0f 00                 cjne A,#15,ds_c2            ; never branches; sets C=1 if cmd < 15
ds_c2:
  F30A: 50 d5                    jnc ds_eat                  ; cmd >= 15: not in the table -> "no key" (stock read erased flash)
  F30C: 90 93 98                 mov DPTR,#0x9398            ; ir_cmd_to_key_table
  F30F: 93                       movc A,@A+DPTR              ; A = table[cmd]
  F310: 02 5d 17                 ljmp 0x5D17                 ; ir_cmd_to_key's tail: mov R7,A ; clr A ; mov 0x6F,A ; ret
            ; fx_auto_off: replaces post_power_on's tail `ljmp ui_clear_screen` (0x55B9). With Dimmer on
            ; Auto OFF, arm the screen-off countdown as a key press would, then take the stock tail call.
            ; Arming before the jump keeps the stack depth as stock; the countdown is only read by the
            ; main loop (0x33DB), so the order against ui_clear_screen does not matter.
fx_auto_off:
  F313: e5 29                    mov A,0x29                  ; g_dimmer_mode: 1 Always ON, 2 Auto OFF
  F315: b4 02 06                 cjne A,#0x02,fx_ao_done
  F318: 75 2f 01                 mov 0x2F,#0x01            ; g_screen_off_hi
  F31B: 75 30 f4                 mov 0x30,#0xF4            ; g_screen_off_lo
fx_ao_done:
  F31E: 02 5d 42                 ljmp 0x5D42                 ; ui_clear_screen, the stock tail call
            ; sv_limit: replaces post_power_on's `lcall audio_chips_init` (0x5596). Cold power-up and the
            ; wake from standby both come through here with the outputs muted, before the first volume
            ; write (volume_apply at 0x510A). Cap g_volume (speakers) and g_volume_hp (headphones) at
            ; their limits, whichever output is active, then go on into audio_chips_init, which returns
            ; to 0x5599: the stack depth is as stock. The capped value is what stock then shows, applies
            ; and saves; the volume keys are not touched.
sv_limit:
  F321: 74 19                    mov A,#0x19               ; g_volume, speakers limit 25
  F323: c3                       clr C
  F324: 95 31                    subb A,0x31               ; limit - volume
  F326: 50 03                    jnc sv_hp                      ; volume <= limit: keep it
  F328: 75 31 19                 mov 0x31,#0x19
sv_hp:
  F32B: 74 14                    mov A,#0x14               ; g_volume_hp, headphones limit 20
  F32D: c3                       clr C
  F32E: 95 52                    subb A,0x52               ; limit - volume
  F330: 50 03                    jnc sv_go                      ; volume <= limit: keep it
  F332: 75 52 14                 mov 0x52,#0x14
sv_go:
  F335: 02 50 d1                 ljmp 0x50D1                 ; audio_chips_init
            ; vp_apply: replaces vol_key_tail's `lcall volume_apply` (0x0F4A; R7 = g_volume), the one write
            ; of the volume to the NJW1194 that all four volume keys share. On Optical and Coaxial without
            ; lock the chip keeps its mute code; on any other input, and with lock, this is volume_apply.
            ; Skipping the write also raises the re-mute request with its 1 s countdown, as Timer0 does when
            ; it sees no lock (t0_remute_no_lock, 0x3EA4). The head and Timer0 sample P4.2 on their own: if
            ; only this test saw it high, the volume would stay unwritten. With the request up, the main
            ; loop mutes and the unmute that follows writes the volume from RAM.
vp_apply:
  F338: e5 47                    mov A,0x47                  ; g_input
  F33A: 24 fe                    add A,#0xFE                 ; input - 2
  F33C: 60 03                    jz vp_digital               ; 2 Optical
  F33E: 14                       dec A
  F33F: 70 0c                    jnz vp_go                   ; not 3 Coaxial either
vp_digital:
  F341: 30 c2 09                 jnb 0xC2,vp_go              ; P4.2 low: lock
  F344: d2 0c                    setb 0x0C                   ; 0x21.4: re-mute request, served by main_tick_tasks
  F346: 75 43 00                 mov 0x43,#0x00              ; g_mute_timer = 100 ticks
  F349: 75 44 64                 mov 0x44,#0x64
  F34C: 22                       ret                         ; no signal: the number changes, the chip does not
vp_go:
  F34D: 02 4d dc                 ljmp 0x4DDC                 ; volume_apply, returns to the tail
            ; mi_switch: replaces input_menu_select's `lcall audio_apply_mute` (0x5892), reached with 0x22.4
            ; cleared and the settings save armed, as input_apply is at 0x5645. Do what input_step and
            ; input_apply do for the Source key: mute, format poll in 10 ticks, unmute countdown 200 ticks,
            ; input_set_hw. Then rejoin input_menu_select at 0x589D, past its `clr P4.0` and the re-init
            ; countdown (0x5895..0x589C, no longer reached): page, refresh countdown, clear, list state.
            ; A jump in and a jump back, so the stack is as deep as in stock when input_set_hw runs, one
            ; call below the key handler, as on the Source key's path.
mi_switch:
  F350: 12 58 d3                 lcall 0x58D3                ; audio_apply_mute: NJW1194 mute code, DAC mute
  F353: 75 4b 00                 mov 0x4B,#0x00            ; g_format_poll: 10 ticks
  F356: 75 4c 0a                 mov 0x4C,#0x0A
  F359: 75 43 00                 mov 0x43,#0x00            ; g_mute_timer: 200 ticks, then mute_timer_expired unmutes
  F35C: 75 44 c8                 mov 0x44,#0xC8
  F35F: af 47                    mov R7,0x47                 ; g_input
  F361: 12 24 d6                 lcall 0x24D6                ; input_set_hw: NJW1194 selector, muxes, receiver, DAC clocking
  F364: 02 58 9d                 ljmp 0x589D                 ; input_menu_select's tail
